13	
14	const prisma = new PrismaClient();
15	
16	const JWT_SECRET = process.env.JWT_SECRET ?? "supersecretkeychangeinproduction";
17	
18	fastify.register(require("fastify-jwt"), {
19	  secret: JWT_SECRET,
20	});
21	
22	// ---------- Error handler ----------
23	fastify.setErrorHandler((error, request, reply) => {
24	  // Map Prisma errors to API error format
25	  if (reply.statusCode === 404) {
26	    reply.send({
27	      error: "Not found",
28	      message: "The requested resource could not be found.",
29	    });
30	  } else {
31	    reply.send({
32	      error: error.message,
33	      message: error.message,
34	    });
35	  }
36	});
37	
38	// ---------- Health endpoint ----------
39	fastify.get("/health", async (_, reply) => {
40	  return { status: "ok" };
41	});
42	
43	// ---------- Auth ----------
44	fastify.post("/api/users", async (request, reply) => {
45	  const { user } = request.body as { user: { username: string; email: string; password: string } };
46	
47	  // Check if user already exists
48	  const existing = await prisma.user.findUnique({ where: { username: user.username } });
49	  if (existing) {
50	    reply.code(400).send({
51	      error: "Validation Error",
52	      message: "Username already exists",
53	    });
54	    return;
55	  }
56	
57	  // Hash password
58	  const hashed = await bcrypt.hash(user.password, 10);
59	
60	  // Create user
61	  const created = await prisma.user.create({
62	    data: {
63	      username: user.username,
64	      email: user.email,
65	      password: hashed,
66	    },
67	  });
68	
69	  // Generate JWT token (expires in 1 hour)
70	  const token = jwt.sign(
71	    { userId: created.id },
72	    JWT_SECRET,
73	    { expiresIn: "1h" },
74	  );
75	
76	  reply.code(201).send({
77	    user: {
78	      id: created.id,
79	      username: created.username,
80	      email: created.email,
81	      token,
82	      bio: null,
83	      image: null,
84	    },
85	  });
86	});
87	
88	// ---------- Login ----------
89	fastify.post("/api/users/login", async (request, reply) => {
90	  const { user } = request.body as { user: { email: string; password: string } };
91	
92	  // Find user by email
93	  const userRecord = await prisma.user.findUnique({ where: { email: user.user.email } });
94	  if (!userRecord || !(await bcrypt.compare(user.user.password, userRecord.password))) {
95	    reply.code(401).send({
96	      error: "Not authorized",
97	      message: "Invalid email or password",
98	    });
99	    return;
100	  }
101	
102	  // Generate JWT token
103	  const token = jwt.sign(
104	    { userId: userRecord.id },
105	    JWT_SECRET,
106	    { expiresIn: "1h" },
107	  );
108	
109	  reply.code(200).send({
110	    user: {
111	      username: userRecord.username,
112	      email: userRecord.email,
113	      bio: userRecord.bio,
114	      image: userRecord.image,
115	      token,
116	    },
117	  });
118	});
119	
120	// ---------- Current user ----------
121	fastify.get("/api/user", async (request, reply) => {
122	  const userId = request.user.userId;
123	  const user = await prisma.user.findUnique({ where: { id: userId } });
124	  if (!user) {
125	    reply.code(404).send({
126	      error: "User not found",
127	      message: "The requested user does not exist.",
128	    });
129	    return;
130	  }
131	
132	  reply.send({
133	    user: {
134	      id: user.id,
135	      username: user.username,
136	      email: user.email,
137	      bio: user.bio,
138	      image: user.image,
139	    },
140	  });
141	});
142	
143	// ---------- Update user ----------
144	fastify.put("/api/user", async (request, reply) => {
145	  const userId = request.user.userId;
146	  const { user } = request.body as { user: { bio?: string; image?: string } };
147	
148	  const updated = await prisma.user.update({
149	    where: { id: userId },
150	    data: {
151	      bio: user.bio ?? null,
152	      image: user.image ?? null,
153	    },
154	  });
155	
156	  // Normalize null for empty string
157	  if (typeof updated.bio === "string" && updated.bio === "") updated.bio = null;
158	  if (typeof updated.image === "string" && updated.image === "") updated.image = null;
159	  if (typeof updated.bio === "null" && updated.bio !== null) updated.bio = null;
160	  if (typeof updated.image === "null" && updated.image !== null) updated.image = null;
161	
162	  reply.send({
163	    user: {
164	      id: updated.id,
165	      username: updated.username,
166	      email: updated.email,
167	      bio: updated.bio,
168	      image: updated.image,
169	      token: request.user.token,
170	    },
171	  });
172	});
173	
174	// ---------- Follow profile ----------
175	fastify.post("/api/profiles/:username/follow", async (request, reply) => {
176	  const userId = request.user.userId;
177	  const username = request.params.username;
178	
179	  // Verify that the target profile belongs to a valid user
180	  const targetUser = await prisma.user.findUnique({ where: { username } });
181	  if (!targetUser) {
182	    reply.code(404).send({
183	      error: "Profile not found",
184	      message: `Profile with username '${username}' does not exist.`,
185	    });
186	    return;
187	  }
188	
189	  // Creates follow relationship (inverse relationship)
190	  await prisma.follow.create({
191	    data: {
192	      followerId: userId,
193	      followingId: targetUser.id,
194	    },
195	  });
196	
197	  reply.code(200).send({
198	    profile: {
199	      userId: targetUser.id,
200	      bio: targetUser.bio,
201	      image: targetUser.image,
202	      following: true,
203	    },
204	  });
205	});
206	
207	// ---------- Unfollow profile ----------
208	fastify.delete("/api/profiles/:username/follow", async (request, reply) => {
209	  const userId = request.user.userId;
210	  const username = request.params.username;
211	
212	  const targetUser = await prisma.user.findUnique({ where: { username } });
213	  if (!targetUser) {
214	    reply.code(404).send({
215	      error: "Profile not found",
216	      message: `Profile with username '${username}' does not exist.`,
217	    });
218	    return;
219	  }
220	
221	  // Delete follow relationship
222	  await prisma.follow.delete({
223	    where: { followerId: userId, followingId: targetUser.id },
224	  });
225	
226	  reply.code(200).send({
227	    profile: {
228	      userId: targetUser.id,
229	      bio: targetUser.bio,
230	      image: targetUser.image,
231	      following: false,
232	    },
233	  });
234	});
235	
236	// ---------- Feed ----------
237	fastify.get("/api/articles/feed", async (request, reply) => {
238	  const userId = request.user.userId;
239	  // Build feed JSON: [{ userId: ..., feed: [{ slug, title, description, body, tagList, createdAt, updatedAt, author: { username, bio, image } }, ...]}]
240	  const followingIds = await prisma.follow.findMany({ where: { followerId: userId } }).map(f => f.followingId);
241	  // Include own articles
242	  followingIds.push(userId);
243	
244	  const articles = await prisma.article.findMany({
245	    where: { author: { id: { in: followingIds } } },
246	    include: { author: true, favoritesCount: true, favorited: true },
247	    orderBy: { updatedAt: "desc" },
248	  });
249	
250	  const profiles = articles.map((a) => ({
251	    userId: a.author.id,
252	    bio: a.author.bio,
253	    image: a.author.image,
254	    username: a.author.username,
255	    following: a.author.id === userId, // whether current user follows this profile
256	    feed: articles.filter((ae) => ae.author.id === a.author.id),
257	  }));
258	
259	  // Sort profiles by updatedAt of their last article descending
260	  profiles.sort((p1, p2) => {
261	    const p2Last = p2.feed[p2.feed.length - 1].updatedAt;
262	    const p1Last = p1.feed[p1.feed.length - 1].updatedAt;
263	    if (!p2Last) return -1;
264	    if (!p1Last) return 1;
265	    return new Date(p2Last) - new Date(p1Last);
266	  });
267	
268	  reply.send({ profiles });
269	});
270	
271	// ---------- Tags ----------
272	fastify.get("/api/tags", async (request, reply) => {
273	  const articles = await prisma.article.findMany({ distinct: true, select: { tagList: true } }).then((articles) => articles.flatMap((a) => a.tagList)).filter((t): t is string => typeof t === "string");
274	  const distinctTags = [...new Set(articles)].sort();
275	  reply.send({ tags: distinctTags });
276	});
277	
278	// ---------- Create article ----------
279	fastify.post("/api/articles", async (request, reply) => {
280	  const userId = request.user.userId;
281	  const { article } = request.body as { article: { title: string; description: string; body: string; tagList?: string[] } };
282	
283	  const created = await prisma.article.create({
284	    data: {
285	      title: article.title,
286	      description: article.description,
287	      body: article.body,
288	      tagList: article.tagList ?? [],
289	      author: { connect: { id: userId } },
290	    },
291	  });
292	
293	  reply.code(201).send({
294	    article: {
295	      slug: created.slug,
296	      title: created.title,
297	      description: created.description,
298	      body: created.body,
299	      tagList: created.tagList,
300	      createdAt: created.createdAt,
301	      updatedAt: created.updatedAt,
302	    },
303	  });
304	});
305	
306	// ---------- List articles by author ----------
307	fastify.get("/api/articles", async (request, reply) => {
308	  const userId = request.user.userId;
309	  const authorUsername = request.query.author;
310	  let authorId;
311	  if (authorUsername) {
312	    authorId = await prisma.user.findUnique({ where: { username: authorUsername } })?.id;
313	    if (!authorId) {
314	      reply.code(404).send({
315	        error: "Not found",
316	        message: `No articles found for author '${authorUsername}'.`,
317	      });
318	      return;
319	    }
320	  } else {
321	    authorId = userId;
322	  }
323	
324	  const articles = await prisma.article.findMany({
325	    where: { author: { id: authorId } },
326	    orderBy: { createdAt: "desc" },
327	  });
328	
329	  const response = articles.map((a) => ({
330	    slug: a.slug,
331	    title: a.title,
332	    description: a.description,
333	    body: a.body,
334	    tagList: a.tagList,
335	    createdAt: a.createdAt,
336	    updatedAt: a.updatedAt,
337	    favorited: false,
338	  }));
339	
340	  reply.send({ articles: response });
341	});
342	
343	// ---------- Get single article ----------
344	fastify.get("/api/articles/:slug", async (request, reply) => {
345	  const { slug } = request.params;
346	  const article = await prisma.article.findUnique({ where: { slug } });
347	  if (!article) {
348	    reply.code(404).send({
349	      error: "Not found",
350	      message: `Article with slug '${slug}' does not exist.`,
351	    });
352	    return;
353	  }
354	
355	  reply.send({
356	    article: {
357	      slug: article.slug,
358	      title: article.title,
359	      description: article.description,
360	      body: article.body,
361	      tagList: article.tagList,
362	      createdAt: article.createdAt,
363	      updatedAt: article.updatedAt,
364	      favorited: false,
365	    },
366	  });
367	});
368	
369	// ---------- Update article ----------
370	fastify.put("/api/articles/:slug", async (request, reply) => {
371	  const userId = request.user.userId;
372	  const { slug } = request.params;
373	  const { article } = request.body as { article: { title?: string; description?: string; body?: string; tagList?: string[] } };
374	
375	  const existing = await prisma.article.findUnique({ where: { slug } });
376	  if (!existing) {
377	    reply.code(404).send({
378	      error: "Not found",
379	      message: `Article with slug '${slug}' does not exist.`,
380	    });
381	    return;
382	  }
383	
384	  // Author must be the article author
385	  if (existing.authorId !== userId) {
386	    reply.code(403).send({
387	      error: "Forbidden",
388	      message: "You are not authorized to edit this article.",
389	    });
390	    return;
391	  }
392	
393	  const updated = await prisma.article.update({
394	    where: { slug },
395	    data: {
396	      title: article.title ?? existing.title,
397	      description: article.description ?? existing.description,
398	      body: article.body ?? existing.body,
399	      tagList: normalizeTags(article.tagList ?? existing.tagList),
400	    },
401	  });
402	
403	  reply.send({
404	    article: {
405	      slug: updated.slug,
406	      title: updated.title,
407	      description: updated.description,
408	      body: updated.body,
409	      tagList: updated.tagList,
410	      createdAt: updated.createdAt,
411	      updatedAt: updated.updatedAt,
412	    },
413	  });
414	});
415	
416	// Helper to normalize tagList: empty array stays empty array, null or containing empty strings becomes empty array
417	function normalizeTags(tags: unknown) {
418	  if (Array.isArray(tags)) {
419	    return tags.map((t) => (t === "" ? null : t)) as (string | null)[];
420	  }
421	  if (tags === null) return null;
422	  return [] as string[];
423	}
424	
425	// ---------- Delete article ----------
426	fastify.delete("/api/articles/:slug", async (request, reply) => {
427	  const userId = request.user.userId;
428	  const { slug } = request.params;
429	  const article = await prisma.article.findUnique({ where: { slug } });
430	  if (!article) {
431	    reply.code(404).send({
432	      error: "Not found",
433	      message: `Article with slug '${slug}' does not exist.`,
434	    });
435	    return;
436	  }
437	
438	  // Author must own the article
439	  if (article.authorId !== userId) {
440	    reply.code(403).send({
441	      error: "Forbidden",
442	      message: "You are not authorized to delete this article.",
443	    });
444	    return;
445	  }
446	
447	  // Delete article
448	  await prisma.article.delete({ where: { slug } });
449	
450	  reply.code(200).send({});
451	});
452	
453	// ---------- Favorite article ----------
454	fastify.post("/api/articles/:slug/favorite", async (request, reply) => {
455	  const userId = request.user.userId;
456	  const { slug } = request.params;
457	
458	  const article = await prisma.article.findUnique({ where: { slug } });
459	  if (!article) {
460	    reply.code(404).send({
461	      error: "Article not found",
462	      message: `Article with slug '${slug}' does not exist.`,
463	    });
464	    return;
465	  }
466	
467	  // Check if already favorited
468	  const existing = await prisma.favorite.findUnique({ where: { articleId: article.id, userId } });
469	  if (existing) {
470	    reply.code(409).send({
471	      error: "Already favorited",
472	      message: `Article is already favorited by this user.`,
473	    });
474	    return;
475	  }
476	
477	  await prisma.favorite.create({
478	    data: {
479	      articleId: article.id,
480	      userId,
481	    },
482	  });
483	
484	  reply.code(201).send({});
485	});
486	
487	// ---------- Unfavorite article ----------
488	fastify.delete("/api/articles/:slug/favorite", async (request, reply) => {
489	  const userId = request.user.userId;
490	  const { slug } = request.params;
491	
492	  const article = await prisma.article.findUnique({ where: { slug } });
493	  if (!article) {
494	    reply.code(404).send({
495	      error: "Article not found",
496	      message: `Article with slug '${slug}' does not exist.`,
497	    });
498	    return;
499	  }
500	
501	  // Delete favorite relationship
502	  await prisma.favorite.delete({
503	    where: { articleId: article.id, userId },
504	  });
505	
506	  reply.code(200).send({});
507	});
508	
509	// ---------- Get profile ----------
510	fastify.get("/api/profiles/:username", async (request, reply) => {
511	  const username = request.params.username;
512	  const profile = await prisma.user.findUnique({ where: { username } });
513	  if (!profile) {
514	    reply.code(404).send({
515	      error: "Profile not found",
516	      message: `Profile with username '${username}' does not exist.`,
517	    });
518	    return;
519	  }
520	
521	  const following = await prisma.follow.findFirst({
522	    where: { followerId: request.user.userId, followingId: profile.id },
523	  });
524	
525	  reply.send({
526	    profile: {
527	      userId: profile.id,
528	      username: profile.username,
529	      bio: profile.bio,
530	      image: profile.image,
531	      following: following ? true : false,
532	    },
533	  });
534	});
535	
536	// ---------- Update profile ----------
537	fastify.put("/api/profiles/:username/update", async (request, reply) => {
538	  const username = request.params.username;
539	  const userId = request.user.userId;
540	  const { profile } = request.body as { profile: { bio?: string; image?: string } };
541	
542	  const target = await prisma.user.findUnique({ where: { username } });
543	  if (!target) {
544	    reply.code(404).send({
545	      error: "Profile not found",
546	      message: `Profile with username '${username}' does not exist.`,
547	    });
548	    return;
549	  }
550	
551	  // Only allow updating own profile (authorization)
552	  if (username !== request.user.userId && userId !== target.id) {
553	    reply.code(403).send({
554	      error: "Forbidden",
555	      message: "You are not authorized to update this profile.",
556	    });
557	    return;
558	  }
559	
560	  const updated = await prisma.user.update({
561	    where: { id: target.id },
562	    data: {
563	      bio: profile.bio ?? null,
