// ---------- Create comment ----------
fastify.post("/api/articles/:slug/comments", async (request, reply) => {
  const userId = request.user.userId;
  const { slug } = request.params;
  const { comment } = request.body as { comment: { body: string } };

  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) {
    reply.code(404).send({
      error: "Article not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  const created = await prisma.comment.create({
    data: {
      articleId: article.id,
      body: comment.body,
      author: { connect: { id: userId } },
    },
  });

  reply.code(201).send({
    comment: {
      id: created.id,
      body: created.body,
      createdAt: created.createdAt,
      updatedAt: created.updatedAt,
      author: { username: userId },
    },
  });
});

// ---------- List comments ----------
fastify.get("/api/articles/:slug/comments", async (request, reply) => {
  const { slug } = request.params;
