      error: "Article not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  const comments = await prisma.comment.findMany({
    where: { articleId: article.id },
    orderBy: { createdAt: "desc" },
  });

  const response = comments.map((c) => ({
    id: c.id,
    body: c.body,
    createdAt: c.createdAt,
    updatedAt: c.updatedAt,
    author: { username: c.author.username },
  }));

  reply.send({ comments: response });
});

// ---------- Delete comment ----------
fastify.delete("/api/articles/:slug/comments/:commentId", async (request, reply) => {
  const userId = request.user.userId;
  const { slug, commentId } = request.params;

  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) {
    reply.code(404).send({
      error: "Article not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  const comment = await prisma.comment.findUnique({
    where: { id: commentId },
  });
  if (!comment) {
    reply.code(404).send({
      error: "Comment not found",
      message: `Comment with id '${commentId}' does not exist.`,
    });
    return;
  }

  // Author must own the comment
  if (comment.authorId !== userId) {
    reply.code(403).send({
      error: "Forbidden",
      message: "You are not authorized to delete this comment.",
    });
    return;
  }

  await prisma.comment.delete({ where: { id: commentId } });

  reply.code(200).send({});
});

// ---------- Start server ----------
const PORT = Number(process.env.PORT ?? 8000);
fastify.listen({ port: PORT }, (err, address) => {
  if (err) {
    fastify.log.error(err);
    process.exit(1);
  }
  fastify.log.info(`Server is running at ${address}`);
});

