import Fastify from "fastify";
import { PrismaClient, Prisma } from "@prisma/client";
import dotenv from "dotenv";
import bcrypt from "bcrypt";
import jwt from "jsonwebtoken";
import { slugify } from "slugify";

dotenv.config();

const fastify = Fastify({
  logger: true,
});

const prisma = new PrismaClient();

const JWT_SECRET = process.env.JWT_SECRET ?? "supersecretkeychangeinproduction";

fastify.register(require("fastify-jwt"), {
  secret: JWT_SECRET,
});

// ---------- Error handler ----------
fastify.setErrorHandler((error, request, reply) => {
  // Map Prisma errors to API error format
  if (reply.statusCode === 404) {
    reply.send({
      error: "Not found",
      message: "The requested resource could not be found.",
    });
  } else {
    reply.send({
      error: error.message,
      message: error.message,
    });
  }
});

// ---------- Health endpoint ----------
fastify.get("/health", async (_, reply) => {
  return { status: "ok" };
});

// ---------- Auth ----------
fastify.post("/api/users", async (request, reply) => {
  const { user } = request.body as { user: { username: string; email: string; password: string } };

  // Check if user already exists
  const existing = await prisma.user.findUnique({ where: { username: user.username } });
  if (existing) {
    reply.code(400).send({
      error: "Validation Error",
      message: "Username already exists",
    });
    return;
  }

  // Hash password
  const hashed = await bcrypt.hash(user.password, 10);

  // Create user
  const created = await prisma.user.create({
    data: {
      username: user.username,
      email: user.email,
      password: hashed,
    },
  });

  // Generate JWT token (expires in 1 hour)
  const token = jwt.sign(
    { userId: created.id },
    JWT_SECRET,
    { expiresIn: "1h" },
  );

  reply.code(201).send({
    user: {
      id: created.id,
      username: created.username,
      email: created.email,
      token,
      bio: null,
      image: null,
    },
  });
});

// ---------- Login ----------
fastify.post("/api/users/login", async (request, reply) => {
  const { user } = request.body as { user: { email: string; password: string } };

  // Find user by email
  const userRecord = await prisma.user.findUnique({ where: { email: user.user.email } });
  if (!userRecord || !(await bcrypt.compare(user.user.password, userRecord.password))) {
    reply.code(401).send({
      error: "Not authorized",
      message: "Invalid email or password",
    });
    return;
  }

  // Generate JWT token
  const token = jwt.sign(
    { userId: userRecord.id },
    JWT_SECRET,
    { expiresIn: "1h" },
  );

  reply.code(200).send({
    user: {
      username: userRecord.username,
      email: userRecord.email,
      bio: userRecord.bio,
      image: userRecord.image,
      token,
    },
  });
});

// ---------- Current user ----------
fastify.get("/api/user", async (request, reply) => {
  const userId = request.user.userId;
  const user = await prisma.user.findUnique({ where: { id: userId } });
  if (!user) {
    reply.code(404).send({
      error: "User not found",
      message: "The requested user does not exist.",
    });
    return;
  }

  reply.send({
    user: {
      id: user.id,
      username: user.username,
      email: user.email,
      bio: user.bio,
      image: user.image,
    },
  });
});

// ---------- Update user ----------
fastify.put("/api/user", async (request, reply) => {
  const userId = request.user.userId;
  const { user } = request.body as { user: { bio?: string; image?: string } };

  const updated = await prisma.user.update({
    where: { id: userId },
    data: {
      bio: user.bio ?? null,
      image: user.image ?? null,
    },
  });

  // Normalize null for empty string
  if (typeof updated.bio === "string" && updated.bio === "") updated.bio = null;
  if (typeof updated.image === "string" && updated.image === "") updated.image = null;
  if (typeof updated.bio === "null" && updated.bio !== null) updated.bio = null;
  if (typeof updated.image === "null" && updated.image !== null) updated.image = null;

  reply.send({
    user: {
      id: updated.id,
      username: updated.username,
      email: updated.email,
      bio: updated.bio,
      image: updated.image,
      token: request.user.token,
    },
  });
});

// ---------- Follow profile ----------
fastify.post("/api/profiles/:username/follow", async (request, reply) => {
  const userId = request.user.userId;
  const username = request.params.username;

  // Verify that the target profile belongs to a valid user
  const targetUser = await prisma.user.findUnique({ where: { username } });
  if (!targetUser) {
    reply.code(404).send({
      error: "Profile not found",
      message: `Profile with username '${username}' does not exist.`,
    });
    return;
  }

  // Creates follow relationship (inverse relationship)
  await prisma.follow.create({
    data: {
      followerId: userId,
      followingId: targetUser.id,
    },
  });

  reply.code(200).send({
    profile: {
      userId: targetUser.id,
      bio: targetUser.bio,
      image: targetUser.image,
      following: true,
    },
  });
});

// ---------- Unfollow profile ----------
fastify.delete("/api/profiles/:username/follow", async (request, reply) => {
  const userId = request.user.userId;
  const username = request.params.username;

  const targetUser = await prisma.user.findUnique({ where: { username } });
  if (!targetUser) {
    reply.code(404).send({
      error: "Profile not found",
      message: `Profile with username '${username}' does not exist.`,
    });
    return;
  }

  // Delete follow relationship
  await prisma.follow.delete({
    where: { followerId: userId, followingId: targetUser.id },
  });

  reply.code(200).send({
    profile: {
      userId: targetUser.id,
      bio: targetUser.bio,
      image: targetUser.image,
      following: false,
    },
  });
});

// ---------- Feed ----------
fastify.get("/api/articles/feed", async (request, reply) => {
  const userId = request.user.userId;
  // Build feed JSON: [{ userId: ..., feed: [{ slug, title, description, body, tagList, createdAt, updatedAt, author: { username, bio, image } }, ...]}]
  const followingIds = await prisma.follow.findMany({ where: { followerId: userId } }).map(f => f.followingId);
  // Include own articles
  followingIds.push(userId);

  const articles = await prisma.article.findMany({
    where: { author: { id: { in: followingIds } } },
    include: { author: true, favoritesCount: true, favorited: true },
    orderBy: { updatedAt: "desc" },
  });

  const profiles = articles.map((a) => ({
    userId: a.author.id,
    bio: a.author.bio,
    image: a.author.image,
    username: a.author.username,
    following: a.author.id === userId, // whether current user follows this profile
    feed: articles.filter((ae) => ae.author.id === a.author.id),
  }));

  // Sort profiles by updatedAt of their last article descending
  profiles.sort((p1, p2) => {
    const p2Last = p2.feed[p2.feed.length - 1].updatedAt;
    const p1Last = p1.feed[p1.feed.length - 1].updatedAt;
    if (!p2Last) return -1;
    if (!p1Last) return 1;
    return new Date(p2Last) - new Date(p1Last);
  });

  reply.send({ profiles });
});

// ---------- Tags ----------
fastify.get("/api/tags", async (request, reply) => {
  const articles = await prisma.article.findMany({ distinct: true, select: { tagList: true } }).then((articles) => articles.flatMap((a) => a.tagList)).filter((t): t is string => typeof t === "string");
  const distinctTags = [...new Set(articles)].sort();
  reply.send({ tags: distinctTags });
});

// ---------- Create article ----------
fastify.post("/api/articles", async (request, reply) => {
  const userId = request.user.userId;
  const { article } = request.body as { article: { title: string; description: string; body: string; tagList?: string[] } };

  const created = await prisma.article.create({
    data: {
      title: article.title,
      description: article.description,
      body: article.body,
      tagList: article.tagList ?? [],
      author: { connect: { id: userId } },
    },
  });

  reply.code(201).send({
    article: {
      slug: created.slug,
      title: created.title,
      description: created.description,
      body: created.body,
      tagList: created.tagList,
      createdAt: created.createdAt,
      updatedAt: created.updatedAt,
    },
  });
});

// ---------- List articles by author ----------
fastify.get("/api/articles", async (request, reply) => {
  const userId = request.user.userId;
  const authorUsername = request.query.author;
  let authorId;
  if (authorUsername) {
    authorId = await prisma.user.findUnique({ where: { username: authorUsername } })?.id;
    if (!authorId) {
      reply.code(404).send({
        error: "Not found",
        message: `No articles found for author '${authorUsername}'.`,
      });
      return;
    }
  } else {
    authorId = userId;
  }

  const articles = await prisma.article.findMany({
    where: { author: { id: authorId } },
    orderBy: { createdAt: "desc" },
  });

  const response = articles.map((a) => ({
    slug: a.slug,
    title: a.title,
    description: a.description,
    body: a.body,
    tagList: a.tagList,
    createdAt: a.createdAt,
    updatedAt: a.updatedAt,
    favorited: false,
  }));

  reply.send({ articles: response });
});

// ---------- Get single article ----------
fastify.get("/api/articles/:slug", async (request, reply) => {
  const { slug } = request.params;
  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) {
    reply.code(404).send({
      error: "Not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  reply.send({
    article: {
      slug: article.slug,
      title: article.title,
      description: article.description,
      body: article.body,
      tagList: article.tagList,
      createdAt: article.createdAt,
      updatedAt: article.updatedAt,
      favorited: false,
    },
  });
});

// ---------- Update article ----------
fastify.put("/api/articles/:slug", async (request, reply) => {
  const userId = request.user.userId;
  const { slug } = request.params;
  const { article } = request.body as { article: { title?: string; description?: string; body?: string; tagList?: string[] } };

  const existing = await prisma.article.findUnique({ where: { slug } });
  if (!existing) {
    reply.code(404).send({
      error: "Not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  // Author must be the article author
  if (existing.authorId !== userId) {
    reply.code(403).send({
      error: "Forbidden",
      message: "You are not authorized to edit this article.",
    });
    return;
  }

  const updated = await prisma.article.update({
    where: { slug },
    data: {
      title: article.title ?? existing.title,
      description: article.description ?? existing.description,
      body: article.body ?? existing.body,
      tagList: normalizeTags(article.tagList ?? existing.tagList),
    },
  });

  reply.send({
    article: {
      slug: updated.slug,
      title: updated.title,
      description: updated.description,
      body: updated.body,
      tagList: updated.tagList,
      createdAt: updated.createdAt,
      updatedAt: updated.updatedAt,
    },
  });
});

// Helper to normalize tagList: empty array stays empty array, null or containing empty strings becomes empty array
function normalizeTags(tags: unknown) {
  if (Array.isArray(tags)) {
    return tags.map((t) => (t === "" ? null : t)) as (string | null)[];
  }
  if (tags === null) return null;
  return [] as string[];
}

// ---------- Delete article ----------
fastify.delete("/api/articles/:slug", async (request, reply) => {
  const userId = request.user.userId;
  const { slug } = request.params;
  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) {
    reply.code(404).send({
      error: "Not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  // Author must own the article
  if (article.authorId !== userId) {
    reply.code(403).send({
      error: "Forbidden",
      message: "You are not authorized to delete this article.",
    });
    return;
  }

  // Delete article
  await prisma.article.delete({ where: { slug } });

  reply.code(200).send({});
});

// ---------- Favorite article ----------
fastify.post("/api/articles/:slug/favorite", async (request, reply) => {
  const userId = request.user.userId;
  const { slug } = request.params;

  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) {
    reply.code(404).send({
      error: "Article not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  // Check if already favorited
  const existing = await prisma.favorite.findUnique({ where: { articleId: article.id, userId } });
  if (existing) {
    reply.code(409).send({
      error: "Already favorited",
      message: `Article is already favorited by this user.`,
    });
    return;
  }

  await prisma.favorite.create({
    data: {
      articleId: article.id,
      userId,
    },
  });

  reply.code(201).send({});
});

// ---------- Unfavorite article ----------
fastify.delete("/api/articles/:slug/favorite", async (request, reply) => {
  const userId = request.user.userId;
  const { slug } = request.params;

  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) {
    reply.code(404).send({
      error: "Article not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  // Delete favorite relationship
  await prisma.favorite.delete({
    where: { articleId: article.id, userId },
  });

  reply.code(200).send({});
});

// ---------- Get profile ----------
fastify.get("/api/profiles/:username", async (request, reply) => {
  const username = request.params.username;
  const profile = await prisma.user.findUnique({ where: { username } });
  if (!profile) {
    reply.code(404).send({
      error: "Profile not found",
      message: `Profile with username '${username}' does not exist.`,
    });
    return;
  }

  const following = await prisma.follow.findFirst({
    where: { followerId: request.user.userId, followingId: profile.id },
  });

  reply.send({
    profile: {
      userId: profile.id,
      username: profile.username,
      bio: profile.bio,
      image: profile.image,
      following: following ? true : false,
    },
  });
});

// ---------- Update profile ----------
fastify.put("/api/profiles/:username/update", async (request, reply) => {
  const username = request.params.username;
  const userId = request.user.userId;
  const { profile } = request.body as { profile: { bio?: string; image?: string } };

  const target = await prisma.user.findUnique({ where: { username } });
  if (!target) {
    reply.code(404).send({
      error: "Profile not found",
      message: `Profile with username '${username}' does not exist.`,
    });
    return;
  }

  // Only allow updating own profile (authorization)
  if (username !== request.user.userId && userId !== target.id) {
    reply.code(403).send({
      error: "Forbidden",
      message: "You are not authorized to update this profile.",
    });
    return;
  }

  const updated = await prisma.user.update({
    where: { id: target.id },
    data: {
      bio: profile.bio ?? null,
      image: profile.image ?? null,
    },
  });

  // Normalize null for empty string
  if (typeof updated.bio === "string" && updated.bio === "") updated.bio = null;
  if (typeof updated.image === "string" && updated.image === "") updated.image = null;
  if (typeof updated.bio === "null" && updated.bio !== null) updated.bio = null;
  if (typeof updated.image === "null" && updated.image !== null) updated.image = null;

  reply.send({
    profile: {
      userId: target.id,
      username: target.username,
      bio: updated.bio,
      image: updated.image,
    },
  });
});

// ---------- Delete profile ----------
fastify.delete("/api/profiles/:username/delete", async (request, reply) => {
  const username = request.params.username;
  const userId = request.user.userId;

  const target = await prisma.user.findUnique({ where: { username } });
  if (!target) {
    reply.code(404).send({
      error: "Profile not found",
      message: `Profile with username '${username}' does not exist.`,
    });
    return;
  }

  // Only allow deleting own profile (authorization)
  if (username !== request.user.userId && userId !== target.id) {
    reply.code(403).send({
      error: "Forbidden",
      message: "You are not authorized to delete this profile.",
    });
    return;
  }

  // Delete follow relationships (inverse)
  await prisma.follow.deleteMany({ where: { followerId: userId, followingId: target.id } });

  // Delete user and cascade related records
  await prisma.user.delete({ where: { id: target.id } });

  reply.code(200).send({});
});

// ---------- Update auth ----------
fastify.put("/api/auth/:username/update", async (request, reply) => {
  const username = request.params.username;
  const { user } = request.body as { user: { bio?: string; image?: string; password?: string } };

  const target = await prisma.user.findUnique({ where: { username } });
  if (!target) {
    reply.code(404).send({
      error: "Profile not found",
      message: `Profile with username '${username}' does not exist.`,
    });
    return;
  }

  // Authorization: only authenticated user can update
  if (!request.user) {
    reply.code(401).send({
      error: "Not authorized",
      message: "Authentication required",
    });
    return;
  }

  if (username !== request.user.userId && request.user.userId !== target.id) {
    reply.code(403).send({
      error: "Forbidden",
      message: "You are not authorized to update this profile.",
    });
    return;
  }

  if (user.bio !== undefined) {
    await prisma.user.update({ where: { id: target.id }, data: { bio: user.bio ?? null } });
  }
  if (user.image !== undefined) {
    await prisma.user.update({ where: { id: target.id }, data: { image: user.image ?? null } });
  }
  if (user.password !== undefined) {
    const hashed = await bcrypt.hash(user.password, 10);
    await prisma.user.update({ where: { id: target.id }, data: { password: hashed } });
  }

  // Normalize null for empty strings
  if (typeof target.bio === "string" && target.bio === "") target.bio = null;
  if (typeof target.image === "string" && target.image === "") target.image = null;
  if (typeof target.bio === "null" && target.bio !== null) target.bio = null;
  if (typeof target.image === "null" && target.image !== null) target.image = null;

  reply.send({
    user: {
      id: target.id,
      username: target.username,
      bio: target.bio,
      image: target.image,
      token: request.user.token,
    },
  });
});

// ---------- Delete auth ----------
fastify.delete("/api/auth/:username/delete", async (request, reply) => {
  const username = request.params.username;
  const userId = request.user.userId;

  const target = await prisma.user.findUnique({ where: { username } });
  if (!target) {
    reply.code(404).send({
      error: "Profile not found",
      message: `Profile with username '${username}' does not exist.`,
    });
    return;
  }

  // Authorization: only authenticated user can delete
  if (!request.user) {
    reply.code(401).send({
      error: "Not authorized",
      message: "Authentication required",
    });
    return;
  }

  if (username !== request.user.userId && userId !== target.id) {
    reply.code(403).send({
      error: "Forbidden",
      message: "You are not authorized to delete this profile.",
    });
    return;
  }

  // Delete follow relationships (inverse)
  await prisma.follow.deleteMany({ where: { followerId: userId, followingId: target.id } });

  // Delete user and cascade related records
  await prisma.user.delete({ where: { id: target.id } });

  reply.code(200).send({});
});

// ---------- Create comment ----------
fastify.post("/api/articles/:slug/comments", async (request, reply) => {
  const userId = request.user.userId;
  const { slug } = request.params;
  const { comment } = request.body as { comment: { body: string } };

  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) {
    reply.code(404).send({
      error: "Article not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  const created = await prisma.comment.create({
    data: {
      articleId: article.id,
      body: comment.body,
      author: { connect: { id: userId } },
    },
  });

  reply.code(201).send({
    comment: {
      id: created.id,
      body: created.body,
      createdAt: created.createdAt,
      updatedAt: created.updatedAt,
      author: { username: userId },
    },
  });
});

// ---------- List comments ----------
fastify.get("/api/articles/:slug/comments", async (request, reply) => {
  const { slug } = request.params;
  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) {
    reply.code(404).send({
      error: "Article not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  const comments = await prisma.comment.findMany({
    where: { articleId: article.id },
    orderBy: { createdAt: "desc" },
  });

  const response = comments.map((c) => ({
    id: c.id,
    body: c.body,
    createdAt: c.createdAt,
    updatedAt: c.updatedAt,
    author: { username: c.author.username },
  }));

  reply.send({ comments: response });
});

// ---------- Delete comment ----------
fastify.delete("/api/articles/:slug/comments/:commentId", async (request, reply) => {
  const userId = request.user.userId;
  const { slug, commentId } = request.params;

  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) {
    reply.code(404).send({
      error: "Article not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  const comment = await prisma.comment.findUnique({
    where: { id: commentId },
  });
  if (!comment) {
    reply.code(404).send({
      error: "Comment not found",
      message: `Comment with id '${commentId}' does not exist.`,
    });
    return;
  }

  // Author must own the comment
  if (comment.authorId !== userId) {
    reply.code(403).send({
      error: "Forbidden",
      message: "You are not authorized to delete this comment.",
    });
    return;
  }

  await prisma.comment.delete({ where: { id: commentId } });

  reply.code(200).send({});
});

// ---------- Start server ----------
const PORT = Number(process.env.PORT ?? 8000);
fastify.listen({ port: PORT }, (err, address) => {
  if (err) {
    fastify.log.error(err);
    process.exit(1);
  }
  fastify.log.info(`Server is running at ${address}`);
});

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

// Users
model User {
  id            Int        @id @default(autoincrement())
  username      String     @unique
  email         String     @unique
  password      String
  token         String?    // JWT token stored (optional for spec)
  createdAt     DateTime   @default(now())
  updatedAt     DateTime   @updatedAt

